/**
 * In their order, without content.
 * @summary List the plans of a version
 */
export const listPlans = (
    versionId: string,
 signal?: AbortSignal
) => {


      return apiClient<Plan[]>(
      {url: `/api/versions/${versionId}/plans`, method: 'GET', signal
    },
      );
    }




export const getListPlansQueryKey = (versionId: string,) => {
    return [
    `/api/versions/${versionId}/plans`
    ] as const;
    }


export const getListPlansQueryOptions = <TData = Awaited<ReturnType<typeof listPlans>>, TError = ErrorType<Error>>(versionId: string, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof listPlans>>, TError, TData>>, }
) => {

const {query: queryOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListPlansQueryKey(versionId);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listPlans>>> = ({ signal }) => listPlans(versionId, signal);





   return  { queryKey, queryFn, enabled: versionId !== null && versionId !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listPlans>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

