/**
 * Multipart fields `name` and `image`: a JPEG, PNG or WebP image (recognised by its content), at most 20 MB (413 file.too_large) and 40 megapixels (422 file.too_many_pixels), stored re-encoded without metadata at most 4096 px on the long side (WebP as PNG). The plan goes after the version's last plan.
 * @summary Add a plan
 */
export const createPlan = (
    versionId: string,
    createPlanBody?: BodyType<CreatePlanBody>,
 signal?: AbortSignal
) => {

      const formData = new FormData();
if(createPlanBody?.image !== undefined) {
 formData.append(`image`, createPlanBody.image);
 }
if(createPlanBody?.name !== undefined) {
 formData.append(`name`, createPlanBody.name instanceof Blob ? createPlanBody.name : new Blob([createPlanBody.name], { type: 'text/plain' }));
 }

      return apiClient<Plan>(
      {url: `/api/versions/${versionId}/plans`, method: 'POST',
      headers: {'Content-Type': 'multipart/form-data', },
       data: formData, signal
    },
      );
    }




export const getCreatePlanMutationKey = () => ['createPlan'] as const;

export const getCreatePlanMutationOptions = <TError = ErrorType<Error>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createPlan>>, TError,CreatePlanMutationVariables, TContext>, }
): UseMutationOptions<Awaited<ReturnType<typeof createPlan>>, TError,CreatePlanMutationVariables, TContext> => {

const mutationKey = getCreatePlanMutationKey();
const {mutation: mutationOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createPlan>>, CreatePlanMutationVariables> = (props) => {
          const {versionId,data} = props ?? {};

          return  createPlan(versionId,data,)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreatePlanMutationResult = NonNullable<Awaited<ReturnType<typeof createPlan>>>
    export type CreatePlanMutationBody = BodyType<CreatePlanBody> | undefined
    export type CreatePlanMutationError = ErrorType<Error>
    export type CreatePlanMutationVariables = {versionId: string;data?: BodyType<CreatePlanBody>}

    /**
 * @summary Add a plan
 */
export const useCreatePlan = <TError = ErrorType<Error>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createPlan>>, TError,CreatePlanMutationVariables, TContext>, }
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof createPlan>>,
        TError,
        CreatePlanMutationVariables,
        TContext
      > => {
      return useMutation(getCreatePlanMutationOptions(options), queryClient);
    }
    /**
 * ids must list every plan of the version exactly once (422 plan.order_mismatch).
 * @summary Reorder the plans of a version
 */
export const reorderPlans = (
    versionId: string,
    planOrder: BodyType<NonReadonly<PlanOrder>>,
 signal?: AbortSignal
) => {


      return apiClient<Plan[]>(
      {url: `/api/versions/${versionId}/plans/order`, method: 'PUT',
      headers: {'Content-Type': 'application/json', },
      data: planOrder, signal
    },
      );
    }




